import{c as r,Q as o,j as d,m as n}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-项目管理","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-项目管理"},"headers":[],"relativePath":"综合知识/软件工程/项目管理.md","filePath":"综合知识/软件工程/项目管理.md","lastUpdated":null}'),a={name:"综合知识/软件工程/项目管理.md"};function s(e,t,l,g,h,i){return o(),d("div",null,[...t[0]||(t[0]=[n('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 基于构件的软件工程（CBSE）理念</li><li>[x] 构件特征（可组装/可部署/文档化/独立/标准化）+ 模型要素</li><li>[x] CBS 开发过程与组装方式</li><li>[x] 进度管理（Gantt 图/PERT 图/关键路径法 / ES-EF-LS-LF）</li><li>[x] 浮动时间（总浮动/自由浮动）</li><li>[x] 软件配置管理（配置项/基线/版本号/CMO）</li><li>[x] 质量管理（质量规划/质量保证/质量控制）</li><li>[x] 风险管理（识别/定性定量分析/应对/项目+技术+商业风险）</li><li>[x] CBSD 5阶段（需求分析定义/架构设计/构件库建立/应用构建/测试发布）</li><li>[x] 软件复用最佳实践</li><li>[x] DCMM 8能力域</li><li>[x] 成本类型（固定/变动/混合）</li><li>[x] 项目范围管理 WBS</li><li>[x] 项目管理四要素</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><p><strong>项目范围定义</strong>是生产项目计划的基础。WBS 基本要求：工作包可控可管理、树形结构通常<strong>不超过6层</strong>、每个工作包必须有<strong>一个</strong>交付成果（非多个）、每个任务有明确定义完成标准。 <strong>项目管理四大要素：</strong> 人员、产品、过程、项目。</p><h3 id="〇、软件复用-★" tabindex="-1">〇、软件复用 ★ <a class="header-anchor" href="#〇、软件复用-★" aria-label="Permalink to &quot;〇、软件复用 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：软件的最佳复用方式是<strong>使用已验证过的开源软件和工具</strong>（不是复制粘贴代码或复用项目文档）。</p></blockquote><h3 id="一、基于构件的软件工程-cbse-★" tabindex="-1">一、基于构件的软件工程（CBSE）★ <a class="header-anchor" href="#一、基于构件的软件工程-cbse-★" aria-label="Permalink to &quot;一、基于构件的软件工程（CBSE）★&quot;">​</a></h3><blockquote><p>核心理念：<strong>&quot;购买而不是重新构造&quot;</strong>，将开发重点从编写新代码转移到基于已有构件的组装。</p></blockquote><p><strong>CBSE 过程：</strong></p><ol><li>系统需求概览 → 2. 识别候选构件 → 3. 根据构件修改需求 → 4. 体系结构设计 → 5. 构件定制与适配 → 6. 组装构件创建系统</li></ol><p><strong>CBS 与传统过程的不同点：</strong></p><table tabindex="0"><thead><tr><th>不同点</th><th>说明</th></tr></thead><tbody><tr><td><strong>早期需要完整需求</strong></td><td>便于尽可能多地识别可复用构件</td></tr><tr><td><strong>根据构件细化需求</strong></td><td>如果可用构件不满足需求，考虑由复用构件支持的相关需求</td></tr><tr><td><strong>设计完成后进一步搜索构件</strong></td><td>在系统体系结构设计完成后，<strong>进一步搜索和设计精化构件</strong></td></tr><tr><td><strong>开发即组装</strong></td><td>开发过程就是将找到的构件集成在一起</td></tr></tbody></table><hr><h3 id="二、构件特征与组装" tabindex="-1">二、构件特征与组装 <a class="header-anchor" href="#二、构件特征与组装" aria-label="Permalink to &quot;二、构件特征与组装&quot;">​</a></h3><p><strong>构件五大特征：</strong> 可组装性（公开接口）、可部署性（自包含）、文档化、独立性、标准化。</p><p><strong>构件模型三要素：</strong> 接口、使用信息（全局唯一标识符）、部署。</p><p><strong>三种组装方式：</strong> 顺序组装、层次组装、叠加组装。</p><table tabindex="0"><thead><tr><th style="text-align:left;">组装方式</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>顺序组装</strong></td><td>数据依次流经一系列构件处理</td><td>清晰的<strong>线性管道</strong>处理过程</td></tr><tr><td style="text-align:left;"><strong>层次组装</strong></td><td>下层为上层提供服务</td><td>分层架构</td></tr><tr><td style="text-align:left;"><strong>叠加组装</strong></td><td>合并两个或多个现有构件功能，形成新接口</td><td>需要合并现有构件功能</td></tr></tbody></table><p><strong>三类不兼容问题：</strong> 参数不兼容、操作不兼容、操作不完备 → 编写<strong>适配器</strong>解决。</p><blockquote><p>⚠️ 常见坑：「用户界面不兼容」不属于构件组装的三类接口不兼容问题。</p></blockquote><p><strong>CBSD 的 5 个主要阶段（不含代码编写）★：</strong></p><ol><li>需求分析和定义 → 2. 架构设计 → 3. 构件库的建立 → 4. 应用软件构建 → 5. 测试和发布</li></ol><blockquote><p>🎯 一句话结论：CBSD <strong>不含单独的&quot;代码编写&quot;阶段</strong>，开发过程就是构件组装过程。CBSD 融合了<strong>螺旋模型</strong>的特征，本质上是<strong>演化型</strong>的。</p></blockquote><p><strong>构件获取4途径：</strong> ①从现有构件中获取 ②通过遗留工程提取 ③购买 COTS ④自行开发新构件 <strong>构件库检索3方法：</strong> ①基于关键字 ②刻面检索 ③超文本检索</p><hr><h3 id="三、进度管理-★" tabindex="-1">三、进度管理 ★ <a class="header-anchor" href="#三、进度管理-★" aria-label="Permalink to &quot;三、进度管理 ★&quot;">​</a></h3><h4 id="进度管理六过程" tabindex="-1">进度管理六过程 <a class="header-anchor" href="#进度管理六过程" aria-label="Permalink to &quot;进度管理六过程&quot;">​</a></h4><p>活动定义 → 活动排序 → 活动资源估算 → 活动历时估算 → 进度计划编制 → 进度控制。</p><h4 id="gantt-图-vs-pert-图" tabindex="-1">Gantt 图 vs PERT 图 <a class="header-anchor" href="#gantt-图-vs-pert-图" aria-label="Permalink to &quot;Gantt 图 vs PERT 图&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比</th><th>Gantt 图（甘特图）</th><th>PERT 图</th></tr></thead><tbody><tr><td><strong>反映并行关系</strong></td><td>能</td><td>不能</td></tr><tr><td><strong>反映依赖关系</strong></td><td>不能</td><td>能</td></tr></tbody></table><h4 id="关键路径法-cpm-★" tabindex="-1">关键路径法（CPM）★ <a class="header-anchor" href="#关键路径法-cpm-★" aria-label="Permalink to &quot;关键路径法（CPM）★&quot;">​</a></h4><blockquote><p>关键路径：项目的<strong>最短工期</strong>，但却是从开始到结束<strong>时间最长的路径</strong>。关键路径可能不止一条且会动态变化。关键活动：最早开始时间 = 最晚开始时间。</p></blockquote><p><strong>四个关键时间：</strong></p><table tabindex="0"><thead><tr><th>时间</th><th>全称</th><th>计算</th></tr></thead><tbody><tr><td><strong>ES</strong>（最早开始）</td><td>Earliest Start</td><td>顺推：所有前置活动 EF 的<strong>最大值</strong></td></tr><tr><td><strong>EF</strong>（最早完成）</td><td>Earliest Finish</td><td><strong>EF = ES + 工期</strong></td></tr><tr><td><strong>LF</strong>（最迟完成）</td><td>Latest Finish</td><td>逆推：所有后续活动 LS 的<strong>最小值</strong></td></tr><tr><td><strong>LS</strong>（最迟开始）</td><td>Latest Start</td><td><strong>LS = LF - 工期</strong></td></tr></tbody></table><p><strong>浮动时间：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>公式</th><th>说明</th></tr></thead><tbody><tr><td><strong>总浮动时间</strong></td><td>LS - ES 或 LF - EF</td><td>不延误项目完工时间的前提下可推迟的时间量</td></tr><tr><td><strong>自由浮动时间</strong></td><td>紧后活动 ES 的最小值 - 本活动 EF</td><td>不延误任何紧后活动最早开始时间</td></tr></tbody></table><blockquote><p>关键活动的总浮动时间为<strong>零</strong>。</p></blockquote><hr><h3 id="四、软件配置管理-★" tabindex="-1">四、软件配置管理 ★ <a class="header-anchor" href="#四、软件配置管理-★" aria-label="Permalink to &quot;四、软件配置管理 ★&quot;">​</a></h3><blockquote><p>配置管理目的：在整个生命周期中<strong>系统地控制配置变更</strong>，维持配置的完整性和可跟踪性。</p></blockquote><p><strong>六大活动</strong>：制订配置管理计划 → 配置标识 → 配置控制 → 配置状态报告 → 配置审计 → 发布管理和交付。</p><p><strong>配置项</strong>：为配置管理设计的硬件/软件或其集合。典型：项目计划书、需求文档、设计文档、源代码、可执行代码、测试用例、运行数据。<strong>经评审和检查通过后</strong>进入配置管理。</p><p><strong>配置项分类：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>内容</th><th>权限</th></tr></thead><tbody><tr><td><strong>基线配置项</strong></td><td>设计文档、源程序等</td><td>向开发人员开放读取</td></tr><tr><td><strong>非基线配置项</strong></td><td>项目计划、报告等</td><td>向 PM、CCB 及相关人员开放</td></tr></tbody></table><blockquote><p>所有配置项操作权限由 <strong>CMO（配置管理员）</strong> 严格管理。</p></blockquote><p><strong>配置项三种状态：</strong></p><table tabindex="0"><thead><tr><th>状态</th><th>触发条件</th><th>版本号格式</th></tr></thead><tbody><tr><td><strong>草稿</strong></td><td>刚建立</td><td><strong>0.YZ</strong>（YZ 递增）</td></tr><tr><td><strong>正式</strong></td><td>通过评审</td><td><strong>X.Y</strong>（第一次为 1.0）</td></tr><tr><td><strong>修改</strong></td><td>更改配置项</td><td><strong>X.YZ</strong>（修改时只增大 Z，完成后 Z=0，增大 XY）</td></tr></tbody></table><hr><h3 id="五、质量管理" tabindex="-1">五、质量管理 <a class="header-anchor" href="#五、质量管理" aria-label="Permalink to &quot;五、质量管理&quot;">​</a></h3><blockquote><p>质量是软件产品满足明确（基本需求）或隐含（期望需求）要求的能力。</p></blockquote><table tabindex="0"><thead><tr><th>过程</th><th>说明</th></tr></thead><tbody><tr><td><strong>质量规划</strong></td><td>识别质量要求和标准，书面描述如何达到</td></tr><tr><td><strong>质量保证</strong></td><td>每隔一定时间通过<strong>质量审计（软件评审）和过程分析</strong>来保证</td></tr><tr><td><strong>质量控制</strong></td><td><strong>实时监控</strong>具体结果，判断是否符合质量标准，消除问题原因</td></tr></tbody></table><hr><h3 id="六、风险管理-★" tabindex="-1">六、风险管理 ★ <a class="header-anchor" href="#六、风险管理-★" aria-label="Permalink to &quot;六、风险管理 ★&quot;">​</a></h3><blockquote><p>风险管理能<strong>避开不利条件、减少损失</strong>，但<strong>完全避开或消除风险是不可能的</strong>。</p></blockquote><p><strong>六大过程：</strong></p><table tabindex="0"><thead><tr><th>过程</th><th>内容</th></tr></thead><tbody><tr><td>风险管理计划编制</td><td>安排如何实施风险管理</td></tr><tr><td><strong>风险识别</strong></td><td>识别已知和可预测风险，形成<strong>风险列表</strong></td></tr><tr><td>风险定性分析</td><td>排序、确定可能性和影响、优先级、类型</td></tr><tr><td>风险定量分析</td><td>灵敏度分析、期望货币价值分析、决策树分析、蒙特卡罗模拟</td></tr><tr><td>风险应对计划</td><td>消极风险（避免/转移/减轻）；积极风险（开拓/分享/强大）</td></tr><tr><td>风险监控</td><td>监控执行、检测残余风险、识别新风险</td></tr></tbody></table><p><strong>宏观三类风险：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>威胁对象</th><th>示例</th></tr></thead><tbody><tr><td><strong>项目风险</strong></td><td>项目计划</td><td>预算、进度、人员、资源、用户需求问题</td></tr><tr><td><strong>技术风险</strong></td><td>质量和交付时间</td><td>设计/实现/接口问题、规格说明多义性、技术不确定性</td></tr><tr><td><strong>商业风险</strong></td><td>系统生存能力</td><td>市场风险、策略风险、销售风险、管理风险、预算风险</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：「仅根据风险产生的后果来对风险排优先级」— 错！风险优先级需综合考虑<strong>概率和影响</strong>。<br> ⚠️ 风险定义：不确定的事件或条件，可能对项目目标产生<strong>正面或负面</strong>影响（不只是负面）。</p></blockquote><hr><h3 id="七、成本管理" tabindex="-1">七、成本管理 <a class="header-anchor" href="#七、成本管理" aria-label="Permalink to &quot;七、成本管理&quot;">​</a></h3><p><strong>成本按性态分类：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>固定成本</strong></td><td>不随业务量变化</td><td>固定资产折旧费、房屋租金</td></tr><tr><td style="text-align:left;"><strong>变动成本</strong></td><td>随业务量变化</td><td>外包费用、直接材料费</td></tr><tr><td style="text-align:left;"><strong>混合成本</strong></td><td>兼有两者特征</td><td>技术开发经费</td></tr></tbody></table><hr><h3 id="八、dcmm-数据管理能力成熟度-★" tabindex="-1">八、DCMM 数据管理能力成熟度 ★ <a class="header-anchor" href="#八、dcmm-数据管理能力成熟度-★" aria-label="Permalink to &quot;八、DCMM 数据管理能力成熟度 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：DCMM 将组织数据管理能力划分为 <strong>8 个能力域</strong>。</p></blockquote><p>8域：数据战略 → 数据治理 → 数据架构 → 数据标准 → 数据质量 → 数据安全 → <strong>数据应用</strong> → <strong>数据生存周期</strong></p>',67)])])}const c=r(a,[["render",s]]);export{p as __pageData,c as default};
